static ssize_t cdns_mhdp_transfer ( struct drm_dp_aux * aux , struct drm_dp_aux_msg * msg ) { struct cdns_mhdp_device * mhdp = dev_get_drvdata ( aux -> dev ) ; int ret ; if ( msg -> request == DP_AUX_NATIVE_WRITE ) { const u8 * buf = msg -> buffer ; unsigned int i ; for ( i = 0 ; i < msg -> size ; ++ i ) { ret = cdns_mhdp_dpcd_write ( mhdp , msg -> address + i , buf [ i ] ) ; if ( ! ret ) { continue ; } dev_err ( mhdp -> dev , "Failed to write DPCD addr %u\n" , msg -> address + i ) ; return ret ; } } else { ret = cdns_mhdp_dpcd_read ( mhdp , msg -> address , msg -> buffer , msg -> size ) ; if ( ret ) { dev_err ( mhdp -> dev , "Failed to read DPCD addr %u\n" , msg -> address ) ; return ret ; } } return msg -> size ; } 